from pathlib import Path
import json,hashlib
tid='DEV-PRED-A2Z-R4P3-ASTRA-PREBUILD-QUEUE-20261008-N1E138'
state=Path.home()/'.local/state/prediction-project-executor'/f'{tid}.json'
req=Path.home()/'.local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4/requests/A2Z-V4-ASTRA-PREBUILD-DIRECT-20261008-R4P3.json'
parts=[]
if state.exists():
    o=json.loads(state.read_text())
    for k in ['status','exit_code','error','detail','claimed_at_utc','finished_at_utc','source_commit','worktree','branch']:
        if k in o: parts.append(k.upper()+'='+str(o.get(k)))
    ops=o.get('operations')
    if isinstance(ops,list):
        for i,x in enumerate(ops,1):
            if isinstance(x,dict):
                parts.append(f'OP{i}_TYPE='+str(x.get('type','')))
                for k in ['status','returncode','exit_code','error']:
                    if k in x: parts.append(f'OP{i}_{k.upper()}='+str(x.get(k)))
else: parts.append('STATE_EXISTS=0')
parts.append('REQUEST_EXISTS='+str(int(req.exists())))
if req.exists():
    b=req.read_bytes(); parts.append('REQUEST_SHA256='+hashlib.sha256(b).hexdigest()); parts.append('REQUEST_SIZE='+str(len(b)))
print('ERROR_CLASS=R4P3_QUEUE_EXECSTATE')
print('ERROR='+'|'.join(parts))
raise SystemExit(1)
